+impl std::error::Error for HookResolveError {
+    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
+        match self {
+            Self::Resolve(error) => Some(error),
+            Self::SecretsInHeader { .. } | Self::HeaderEnvNotAllowed { .. } => None,
+        }
+    }
