+    pub name:           Option<String>,
+    pub event:          HookEvent,
+    pub hook_type:      Option<RuntimeHookType>,
+    pub matcher:        Option<String>,
+    pub blocking:       Option<bool>,
+    pub timeout_ms:     Option<u64>,
+    pub sandbox:        Option<bool>,
