+        if let Some(ms) = self.timeout_ms {
+            return StdDuration::from_millis(ms);
+        }
+        let default_ms = match self.hook_type {
+            Some(RuntimeHookType::Prompt { .. }) => 30_000,
+            _ => 60_000,
+        };
+        StdDuration::from_millis(default_ms)
+    }
